/// Every signature the radio bypass can locate without an ELF.
pub fn radio_bypass() -> Vec<Signature> {
    [
        ("esp_phy_enable", ESP_PHY_ENABLE),
        ("esp_wifi_init", ESP_WIFI_INIT),
        ("esp_wifi_set_mode", ESP_WIFI_SET_MODE),
        ("esp_wifi_set_config", ESP_WIFI_SET_CONFIG),
        ("esp_wifi_start", ESP_WIFI_START),
        ("esp_wifi_stop", ESP_WIFI_STOP),
        ("esp_wifi_scan_start", ESP_WIFI_SCAN_START),
    ]
    .into_iter()
    .map(|(name, code)| Signature::from_xtensa(name, code))
    .collect()
}

/// The signature for one symbol, if we have one.
pub fn find(name: &str) -> Option<Signature> {
    radio_bypass().into_iter().find(|s| s.name == name)
}
